// Check every line added in this push for leaked keys and risky patterns.
const push = $('GitHub push').first().json.body || {};
const files = $input.first().json.files || [];
const RULES = [
  { re: /sk-(?:proj-)?[A-Za-z0-9_-]{24,}/, what: 'OpenAI key pasted in code' },
  { re: /sk-ant-[A-Za-z0-9_-]{20,}/, what: 'Anthropic key pasted in code' },
  { re: /[sr]k_live_[A-Za-z0-9]{16,}/, what: 'Stripe live key pasted in code' },
  { re: /AKIA[0-9A-Z]{16}/, what: 'AWS access key pasted in code' },
  { re: /gh[pousr]_[A-Za-z0-9]{30,}/, what: 'GitHub token pasted in code' },
  { re: /AIza[0-9A-Za-z_-]{35}/, what: 'Google API key pasted in code' },
  { re: /(VITE_|NEXT_PUBLIC_|REACT_APP_|EXPO_PUBLIC_)\w*(SECRET|SERVICE_ROLE|OPENAI|ANTHROPIC|STRIPE_SECRET|RESEND)/, what: 'Secret key read in browser code' },
  { re: /dangerouslyAllowBrowser\s*:\s*true/, what: 'AI SDK allowed to run in the browser (sends your key to visitors)' },
];
const found = [];
for (const f of files) {
  if (/(^|\/)\.env($|\.(?!example|sample))/.test(f.filename)) found.push({ file: f.filename, line: '-', what: '.env file was committed. Every key in it is now public.' });
  let n = 0;
  for (const ln of String(f.patch || '').split('\n')) {
    const m = ln.match(/^@@ -\d+(?:,\d+)? \+(\d+)/); if (m) { n = +m[1] - 1; continue; }
    if (ln.startsWith('-')) continue; n++;
    if (!ln.startsWith('+')) continue;
    for (const r of RULES) if (r.re.test(ln)) found.push({ file: f.filename, line: n, what: r.what });
  }
}
if (!found.length) return [];
const repo = push.repository?.full_name || 'your repo';
const who = push.pusher?.name || 'someone';
const text = `Flowscope found ${found.length} problem${found.length > 1 ? 's' : ''} in the push by ${who} to ${repo}:\n\n` +
  found.map(f => `- ${f.what} (${f.file}, line ${f.line})`).join('\n') +
  `\n\nWhat to do now:\n1. Make a new key in that service's dashboard and delete the old one. Removing it from the code does not undo a leak.\n2. Move keys into .env and read them only in server code.\n3. Add this rule to AGENTS.md so your AI stops doing it: "Never put API keys in code or in VITE_/NEXT_PUBLIC_ variables."\n\nCommit: ${push.compare || ''}`;
return [{ json: { repo, count: found.length, findings: found, subject: `Flowscope: ${found.length} leaked key${found.length > 1 ? 's' : ''} in ${repo}`, text } }];
